    အကောင်အထည်ဖော်မှု = တန်ဖိုးယူ.import_module('화면요소시험')
    ချိတ်ဆက်ပုံတန်ဖိုး = {'wait': 'စောင့်', 'x': 'xတည်နေရာအမှတ်', 's': 'အက္ခရာစဉ်ဒေတာ', 'i': 'အစဉ်အမှတ်', 'sel': '선택기', 'seconds': 'စက္ကန့်ယူနစ်', 'log': 'မှတ်တမ်းမှတ်တမ်းတစ်ခု', 'data': 'ဒေတာ', 'at': 'လက်ရှိနေရာ', 'send': 'ပို့', 'main': 'လုပ်ဆောင်', 'req': 'တောင်းဆိုချက်တန်ဖိုး', 'hot': '바로가기', 'pump': 'ကိုင်တွယ်ရာဖြစ်ရပ်', 'ROOT': 'စီမံကိန်းအမြစ်', 'marker': '확인표시', 'b': 'ဒုတိယတန်ဖိုး', 'command': 'အမိန့်', 'shell': 'အမိန့်ဝင်း', 'f': 'ဖိုင်အချက်', 'click': '누르기', 'k': '셋째순번', 'c': 'အက္ခရာကုဒ်', 'r': 'ပြန်ပေးတန်ဖိုး', 'p': 'ဒေတာနေရာ', 'command_mode': 'အမိန့်နည်းစနစ်', 'end': 'အဆုံးအရွေ့', 'classes': 'အတန်းလမ်းကြောင်း', 'key': '누름값', 'y': 'yတည်နေရာအမှတ်', 'result': 'ရလဒ်', 'report': '검증기록', 'dest': 'ဦးတည်ရာတန်ဖိုးနေရာ', 'work': 'လုပ်ဆောင်လမ်း', 'qmp': '모의제어접속'}
    for ယခင်အချက်အလက်တစ်ခု, လက်ရှိအချက်အလက်တစ်ခု in ချိတ်ဆက်ပုံတန်ဖိုး.items():
        if hasattr(အကောင်အထည်ဖော်မှု, လက်ရှိအချက်အလက်တစ်ခု): globals()[ယခင်အချက်အလက်တစ်ခု] = getattr(အကောင်အထည်ဖော်မှု, လက်ရှိအချက်အလက်တစ်ခု)
